const updateStaffProfile = `-- name: UpdateStaffProfile :exec
UPDATE users
SET name              = $1,
    email             = $2,
    email_verified_at = CASE WHEN email IS NOT DISTINCT FROM $2 THEN email_verified_at END,
    phone             = $3,
    updated_at        = now()
WHERE user_id = $4
`

type UpdateStaffProfileParams struct {
	Name   string
	Email  *string
	Phone  *string
	UserID string
}

// A changed email isn't verified: whoever set it didn't prove the user owns
// it.
func (q *Queries) UpdateStaffProfile(ctx context.Context, arg UpdateStaffProfileParams) error {
	_, err := q.db.Exec(ctx, updateStaffProfile,
		arg.Name,
		arg.Email,
		arg.Phone,
		arg.UserID,
	)
	return err
}
